import * as path from 'path';
import { fileURLToPath } from 'url';
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PROVIDER_TEMPLATES = {
    openai: {
        models: ['gpt-4o', 'gpt-4o-mini', 'gpt-4-turbo', 'gpt-3.5-turbo'],
        defaultModel: 'gpt-4o-mini',
        envVar: 'OPENAI_API_KEY',
    },
    anthropic: {
        models: ['claude-3-5-sonnet-20241022', 'claude-3-5-haiku-20241022', 'claude-3-opus-20240229'],
        defaultModel: 'claude-3-5-sonnet-20241022',
        envVar: 'ANTHROPIC_API_KEY',
    },
    gemini: {
        models: ['gemini/gemini-1.5-pro', 'gemini/gemini-1.5-flash', 'gemini/gemini-flash-latest'],
        defaultModel: 'gemini/gemini-flash-latest',
        envVar: 'GEMINI_API_KEY',
    },
    ollama: {
        models: ['llama3.1', 'llama3.2', 'mistral', 'codellama'],
        defaultModel: 'llama3.1',
        envVar: 'OLLAMA_BASE_URL',
    },
    custom: {
        models: ['custom'],
        defaultModel: 'custom',
        envVar: 'CUSTOM_API_KEY',
    },
};
export function getProviderTemplates() {
    return PROVIDER_TEMPLATES;
}
export function generateEnvExample(config) {
    const lines = [
        '# ICO-Cache Configuration',
        '# Generated by `ico-cache init`',
        '# Copy this file to .env and fill in your values',
        '',
        '# ============================================',
        '# LLM Provider Configuration',
        '# ============================================',
        `LLM_PROVIDER=${config.provider.provider}`,
        `LLM_MODEL=${config.provider.model}`,
    ];
    if (config.provider.provider !== 'ollama') {
        lines.push(`${PROVIDER_TEMPLATES[config.provider.provider]?.envVar || 'API_KEY'}=your-api-key-here`);
    }
    else {
        lines.push(`OLLAMA_BASE_URL=http://localhost:11434`);
    }
    if (config.provider.baseUrl) {
        lines.push(`LLM_BASE_URL=${config.provider.baseUrl}`);
    }
    lines.push('', '# ============================================', '# ICO-Cache Gateway Configuration', '# ============================================', `GATEWAY_ENABLED=${config.gateway.enabled ? 'true' : 'false'}`, `GATEWAY_HOST=${config.gateway.host}`, `GATEWAY_PORT=${config.gateway.port}`, '', '# API Keys for gateway access (key: tenant_id)', '# Generate secure keys with: openssl rand -hex 32', 'API_KEYS={"your-secure-key-here": "default"}', '', '# ============================================', '# Backend Services', '# ============================================', 'REDIS_HOST=localhost', 'REDIS_PORT=6379', 'REDIS_AUTH=myredissecret', 'QDRANT_HOST=localhost', 'QDRANT_PORT=6333', '', '# ============================================', '# Observability (Optional)', '# ============================================', 'LANGFUSE_HOST=http://localhost:3000', 'LANGFUSE_PUBLIC_KEY=', 'LANGFUSE_SECRET_KEY=', 'OTEL_EXPORTER_OTLP_ENDPOINT=', '', '# ============================================', '# Environment', '# ============================================', 'ENVIRONMENT=development', 'LOG_LEVEL=INFO', 'LOG_JSON=true');
    return lines.join('\n');
}
export function generateDockerCompose(config) {
    const services = [
        'version: "3.8"',
        '',
        'services:',
        '  ico-cache-api:',
        '    image: ico-cache-api:latest',
        '    build:',
        '      context: .',
        '      dockerfile: Dockerfile.api',
        '    depends_on:',
        '      - qdrant',
        '      - redis',
        '    environment:',
        '      ENVIRONMENT: ${ENVIRONMENT:-development}',
        '      API_KEYS: ${API_KEYS:?set API_KEYS to a JSON api-key-to-tenant map}',
        '      INGEST_ROOT_DIR: /app/data/ingest',
        `      LLM_MODEL: ${config.provider.model}`,
    ];
    if (config.provider.provider !== 'ollama') {
        const envVar = PROVIDER_TEMPLATES[config.provider.provider]?.envVar || 'API_KEY';
        services.push(`      ${envVar}: ${envVar}`);
    }
    else {
        services.push('      OLLAMA_BASE_URL: ${OLLAMA_BASE_URL:-http://host.docker.internal:11434}');
    }
    if (config.provider.baseUrl) {
        services.push(`      LLM_BASE_URL: ${config.provider.baseUrl}`);
    }
    services.push('      LLM_TIMEOUT_SECONDS: 60', '      LLM_MAX_RETRIES: 3', '      REDIS_HOST: redis', '      REDIS_PORT: 6379', '      REDIS_AUTH: ${REDIS_AUTH:-myredissecret}', '      QDRANT_HOST: qdrant', '      QDRANT_PORT: 6333', '      LANGFUSE_HOST: ${LANGFUSE_HOST:-http://localhost:3000}', '      LANGFUSE_PUBLIC_KEY: ${LANGFUSE_PUBLIC_KEY:-}', '      LANGFUSE_SECRET_KEY: ${LANGFUSE_SECRET_KEY:-}', '      OTEL_EXPORTER_OTLP_ENDPOINT: ${OTEL_EXPORTER_OTLP_ENDPOINT:-}', '      LOG_LEVEL: ${LOG_LEVEL:-INFO}', '      LOG_JSON: ${LOG_JSON:-true}', '    ports:', `      - "${config.gateway.port}:8000"`, '    volumes:', '      - ./data/ingest:/app/data/ingest', '    restart: unless-stopped', '', '  qdrant:', '    image: qdrant/qdrant:latest', '    ports:', '      - "127.0.0.1:6333:6333"', '      - "127.0.0.1:6334:6334"', '    volumes:', '      - qdrant_data:/qdrant/storage', '    restart: unless-stopped', '', '  redis:', '    image: redis:7', '    command: \'--requirepass ${REDIS_AUTH:-myredissecret} --maxmemory-policy noeviction\'', '    ports:', '      - "127.0.0.1:6379:6379"', '    volumes:', '      - redis_data:/data', '    restart: unless-stopped', '', 'volumes:', '  qdrant_data:', '    driver: local', '  redis_data:', '    driver: local');
    return services.join('\n');
}
export function generateIntegrationCode(config, projectType) {
    if (projectType === 'python' || projectType === 'mixed') {
        return generatePythonIntegration(config);
    }
    return generateNodeIntegration(config);
}
function generatePythonIntegration(config) {
    const apiKey = Object.keys(config.gateway.apiKeys)[0] || 'your-api-key';
    return `#!/usr/bin/env python
"""
ICO-Cache Python Integration Example
Generated by \`ico-cache init\`
Run: python ico_cache_integration.py
"""

import os
from ico_cache import IcoCache

# Initialize ICO-Cache client
cache = IcoCache(
    base_url="http://localhost:${config.gateway.port}",
    api_key="${apiKey}",
)

async def main():
    # Example: Cache an LLM call
    query = "What is the capital of France?"
    context = "Geography question"
    
    async def call_llm():
        # Your existing LLM call here
        # This is a placeholder - replace with your actual LLM call
        return "Paris is the capital of France."
    
    # This will check cache first, call LLM on miss, and store result
    response = await cache.resolve(query, context, call_llm)
    print(f"Response: {response}")

if __name__ == "__main__":
    import asyncio
    asyncio.run(main())
`;
}
function generateNodeIntegration(config) {
    const apiKey = Object.keys(config.gateway.apiKeys)[0] || 'your-api-key';
    return `/**
 * ICO-Cache Node.js Integration Example
 * Generated by \`ico-cache init\`
 * Run: node ico_cache_integration.js
 */

import { icoCache } from 'ico-cache-js';

// Initialize ICO-Cache client
const cache = icoCache({
  baseUrl: 'http://localhost:${config.gateway.port}',
  apiKey: '${apiKey}',
});

async function main() {
  // Example: Cache an LLM call
  const query = 'What is the capital of France?';
  const context = 'Geography question';
  
  async function callLLM() {
    // Your existing LLM call here
    // This is a placeholder - replace with your actual LLM call
    return 'Paris is the capital of France.';
  }
  
  // This will check cache first, call LLM on miss, and store result
  const response = await cache.resolve(query, context, callLLM);
  console.log('Response:', response);
}

main().catch(console.error);
`;
}
export function generateGatewayConfig(config) {
    return `{
  "gateway": {
    "enabled": ${config.gateway.enabled},
    "host": "${config.gateway.host}",
    "port": ${config.gateway.port},
    "apiKeys": ${JSON.stringify(config.gateway.apiKeys, null, 2)}
  },
  "provider": {
    "provider": "${config.provider.provider}",
    "model": "${config.provider.model}",
    "baseUrl": "${config.provider.baseUrl || ''}"
  },
  "backends": {
    "redis": {
      "host": "localhost",
      "port": 6379,
      "auth": "myredissecret"
    },
    "qdrant": {
      "host": "localhost",
      "port": 6333
    }
  }
}`;
}
